<?php
namespace App\Livewire;
use App\Models\PostalPackage;
use App\Models\PostalCampaign;
use Livewire\Component;
use Livewire\WithPagination;
use Illuminate\Pagination\LengthAwarePaginator;

class PostalCampaignManager extends Component
{
    use WithPagination;
    public array $selectedEvents=[]; public string $eventFilter=''; public string $scope='nacional'; public string $source='all'; public string $from=''; public string $to=''; public int $limit=50; public string $campaignName='Campana postal'; public int $intervalSeconds=30; public bool $testMode=true; public string $template='Hola {recipient}, tu paquete {tracking_number} esta en estado {current_event}.'; public ?int $editingCampaignId=null; public string $editingCampaignName='';
    public function mount(string $scope='nacional'): void { $this->scope=in_array($scope,['nacional','internacional'],true)?$scope:'nacional'; $this->source=$this->scope==='nacional'?'siop':'sitra'; }
    public function updating($field): void { if(in_array($field,['source','from','to','limit']))$this->resetPage(); }
    public function applyFilters(): void { $this->limit = min(1000, max(1, (int) $this->limit)); $this->selectedEvents = $this->eventFilter === '' ? [] : [$this->eventFilter]; $this->resetPage(); }
    public function updatedLimit($value): void { $this->limit = min(1000, max(1, (int) $value)); $this->resetPage(); }
    public function updatedIntervalSeconds($value): void { $this->intervalSeconds = max(30, (int) $value); }
    public function clearFilters(): void { $this->selectedEvents=[]; $this->eventFilter=''; $this->from=''; $this->to=''; $this->limit=50; $this->resetPage(); }
    public function filterByEvent(string $event): void { $this->eventFilter = $this->selectedEvents === [$event] ? '' : $event; $this->applyFilters(); }
    private function packageQuery(bool $filter=true){$q=PostalPackage::where('scope',$this->scope)->where('source',$this->scope==='nacional'?'siop':'sitra')->whereNotNull('tracking_number')->whereRaw("trim(tracking_number) <> ''")->whereNotNull('phone')->whereRaw("trim(phone) <> ''");if($filter&&$this->selectedEvents)$this->applyEventFilter($q);if($this->from)$q->whereDate('updated_at_api','>=',$this->from);if($this->to)$q->whereDate('updated_at_api','<=',$this->to);return $q;}
    private function applyEventFilter($q): void {$q->where(function($nested){foreach($this->selectedEvents as $event){foreach($this->aliases($event) as $term)$nested->orWhere('current_event','ilike','%'.$term.'%');}});}
    private function aliases(string $event): array {$key=mb_strtolower($event);return match(true){str_contains($key,'origen y')=>['origen','llegada','entrada'],str_contains($key,'aduana')=>['aduana'],str_contains($key,'distribuci')=>['distribuci','ubicacion nacional','ubicación nacional'],str_contains($key,'ultima')||str_contains($key,'última')=>['ultima milla','última milla','repart'],str_contains($key,'recibido destino')=>['destino'],str_contains($key,'recibido origen')=>['recibid','origen'],str_contains($key,'en camino')=>['camino','transit'],str_contains($key,'cartero')=>['cartero','repart'],str_contains($key,'entregado')=>['entreg','delivered'],str_contains($key,'cancelado')=>['cancel','detenid'],default=>[$event]};}
    public function getPackagesProperty(){ $perPage=15; $page=$this->getPage(); $max=max(1,$this->limit); $items=$this->packageQuery()->orderByDesc('updated_at_api')->orderByDesc('id')->get()->take($max)->values(); return new LengthAwarePaginator($items->forPage($page,$perPage)->values(),$items->count(),$perPage,$page,['path'=>request()->url(),'pageName'=>'page']); }
    public function getEventSummaryProperty(): array {$summary=[];$labels=$this->scope==='internacional'?['Origen y llegada','Aduana','Distribución nacional','Última milla','Entregado','Importación detenida']:['Recibido Origen','En Camino','Recibido Destino','Cartero','Entregado','Cancelado'];foreach($labels as $label)$summary[$label]=0;foreach($this->packageQuery(true)->pluck('current_event') as $event){$label=$this->bucket((string)$event);if(array_key_exists($label,$summary))$summary[$label]++;}return $summary;}
    private function bucket(string $event): string {$v=mb_strtolower($event);if($this->scope==='internacional'){if(str_contains($v,'aduana'))return'Aduana';if(str_contains($v,'distribuci')||str_contains($v,'ubicacion nacional')||str_contains($v,'ubicación nacional'))return'Distribución nacional';if(str_contains($v,'milla')||str_contains($v,'repart'))return'Última milla';if(str_contains($v,'entreg'))return'Entregado';if(str_contains($v,'detenid'))return'Importación detenida';if(str_contains($v,'origen')||str_contains($v,'llegada')||str_contains($v,'entrada'))return'Origen y llegada';}else{if(str_contains($v,'cartero'))return'Cartero';if(str_contains($v,'entreg'))return'Entregado';if(str_contains($v,'destino'))return'Recibido Destino';if(str_contains($v,'camino')||str_contains($v,'transit'))return'En Camino';if(str_contains($v,'origen')||str_contains($v,'recibid'))return'Recibido Origen';if(str_contains($v,'cancel'))return'Cancelado';}return $event?:'Sin evento';}
    public function getTotalFilteredProperty(): int{return min($this->limit,$this->packageQuery()->count());}public function getVisibleProperty(): int{return$this->packages->count();}
    public function prepareCampaign(): void {$this->intervalSeconds=max(30,(int)$this->intervalSeconds);$this->validate(['campaignName'=>'required','limit'=>'required|integer|min:1|max:1000','intervalSeconds'=>'required|integer|min:30','template'=>'required']);$q=$this->packageQuery()->orderByDesc('updated_at_api')->orderByDesc('id');$packages=$q->limit($this->limit)->get();$campaign=PostalCampaign::create(['user_id'=>auth()->id(),'name'=>$this->campaignName,'filters'=>['scope'=>$this->scope,'source'=>$this->source,'from'=>$this->from,'to'=>$this->to,'limit'=>$this->limit],'events'=>$this->selectedEvents,'template'=>$this->template,'interval_seconds'=>$this->intervalSeconds,'test_mode'=>$this->testMode,'status'=>'prepared','total'=>$packages->count(),'pending'=>$packages->count()]);foreach($packages as $package)$campaign->messages()->create(['postal_package_id'=>$package->id,'phone'=>$package->phone,'message'=>strtr($this->template,['{recipient}'=>$package->recipient??'cliente','{tracking_number}'=>$package->tracking_number,'{current_event}'=>$package->current_event??'actualizado'])]);session()->flash('campaignCreated','Campana preparada con '.$packages->count().' paquetes.');}
    public function getCampaignHistoryProperty(){return PostalCampaign::withCount('messages')->latest()->limit(20)->get();}
    public function editCampaign(int $id): void {$campaign=PostalCampaign::findOrFail($id);$this->editingCampaignId=$campaign->id;$this->editingCampaignName=$campaign->name;}
    public function saveCampaignEdit(): void {$this->validate(['editingCampaignName'=>'required|string|max:120']);PostalCampaign::whereKey($this->editingCampaignId)->update(['name'=>$this->editingCampaignName]);$this->editingCampaignId=null;$this->editingCampaignName='';}
    public function render(){return view('livewire.postal-campaign-manager-root');}
}
